INSERT INTO `Center` (`id`, `name`, `slug`, `tagline`, `logoUrl`, `heroMediaType`, `heroMediaUrl`, `aboutContent`, `profilePdfUrl`, `isPublished`, `createdAt`, `updatedAt`) VALUES ('cmtjqjgvw000dtwu2ntmpj4r6','Center for Innovation & Tech Transfer','center-for-innovation','Mendorong Akselerasi Riset & Komersialisasi Teknologi Masa Depan','https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=200&h=200&fit=crop','IMAGE','https://images.unsplash.com/photo-1522071820081-009f0129c71c?w=1200&h=600&fit=crop','<p>Center for Innovation &amp; Tech Transfer berkomitmen penuh dalam menghubungkan hasil riset akademik tingkat tinggi dengan industri riil. Kami mengelola akselerasi startup berbasis teknologi, paten riset, dan transfer teknologi skala nasional maupun internasional.</p>',NULL,1,'2026-09-02 06:48:53.564','2026-09-03 02:16:08.036');
INSERT INTO `Center` (`id`, `name`, `slug`, `tagline`, `logoUrl`, `heroMediaType`, `heroMediaUrl`, `aboutContent`, `profilePdfUrl`, `isPublished`, `createdAt`, `updatedAt`) VALUES ('cmtjqjgwh000itwu2bykjl1ae','Business Strategy & Transformation Center','business-strategy-center','Mitra Strategis Pendampingan Transformasi Bisnis Berkelanjutan','https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=200&h=200&fit=crop','VIDEO','https://www.youtube.com/embed/dQw4w9WgXcQ','<p>Pusat Studi Strategi Bisnis memberikan konsultasi eksekutif untuk korporasi skala menengah hingga multinasional. Fokus kami mencakup restrukturisasi organisasi dan ESG.</p>',NULL,1,'2026-09-02 06:48:53.586','2026-09-03 02:16:08.101');
